          alt: "ด้านบนเป็นภาพโพรบ: ปลายวัด สวิตช์ ×1/×10 บนด้าม ปากคีบกราวด์ สายโคแอกซ์ ทริมเมอร์ชดเชยในกล่องใกล้ขั้ว BNC ด้านล่าง 3 ช่องแสดงคลื่นสี่เหลี่ยมจากขั้ว CAL: ซ้ายขาดชดเชย มุมขาขึ้นมนค่อย ๆ โค้งขึ้น กลางพอดี เหลี่ยมเรียบ ขวาเกินชดเชย มีหนามแหลมที่ขอบขาขึ้นและขาลง",
