          title: "ข้อห้ามเด็ดขาด",
          md: "- **ห้ามวัดไฟบ้าน 230 V หรือวงจรที่ไม่มีหม้อแปลงแยกด้วยโพรบปกติ** แม้ตั้ง ×10 ก็ตาม งานไฟเมนต้องใช้ **โพรบผลต่างแรงดันสูง (high-voltage differential probe)** ที่มีพิกัด CAT เหมาะสม และเป็นงานสาธิตของครูเท่านั้น (S3)\n- **ห้ามตัดหรือดัดแปลงขาดินของปลั๊กสโคป** (เรียกว่าทำให้สโคป “ลอย” หรือ floating) เพื่อเลี่ยงปัญหากราวด์ ตัวถังทั้งเครื่องอาจมีแรงดันอันตรายโดยไม่มีอะไรตัดไฟ\n- **ปากคีบกราวด์ทุกเส้นต่อที่จุดเดียวกัน** ใช้ 2 โพรบก็ต้องหนีบที่กราวด์ร่วมจุดเดียว\n- ห้ามเกินพิกัดแรงดันที่พิมพ์ข้างขั้ว BNC และบนโพรบ (ขึ้นกับรุ่น)\n- ปิด OUTPUT ของเครื่องกำเนิดก่อนต่อหรือย้ายสายทุกครั้ง",
